// The extra commands of the tool register: one line each, with the call the
// integration test makes and what it must return. `node scripts/dev/gen-tools.js`
// turns this file into the registry table (crates/agentgo-shell-bridge/src/extra.rs)
// and the test reads it directly, so a command cannot be listed without a test.
//
// alias: [name, target command, preset params, description, test params, expect]
//   expect: a JS expression over the result `r`, or "!code" for an expected
//   refusal (an operator-only command answers policy.denied to the agent,
//   which also proves the name reaches the right command).
// page:  [name, description, test params, expect]   (implemented in tools.js)
// cdp:   [name, DevTools method, default params, description, test params, expect]
//   Only methods that change emulation or read state: nothing that clicks,
//   types or runs page script (those go through the gated commands).
// unsupported: [name, reason]   names this browser cannot provide
// REF.<id> in test params is replaced by the reference of the fixture element
// with that id.

const key = (name, k, modifiers) => [name, "keyboard.press", modifiers ? { key: k, modifiers } : { key: k }, `Press ${modifiers ? modifiers.join("+") + "+" : ""}${k}.`, {}, "r.key"];

